class FinanceReconciliationSummary {final int customerInvoices,customerOpen,farmerOpen,bankOpen;final double customerOpenAmount,farmerOpenAmount,unbatched,bankOpenAmount,sourceAmount,matchedAmount,unreconciled;final double percent;const FinanceReconciliationSummary({required this.customerInvoices,required this.customerOpen,required this.customerOpenAmount,required this.farmerOpen,required this.farmerOpenAmount,required this.unbatched,required this.bankOpen,required this.bankOpenAmount,required this.sourceAmount,required this.matchedAmount,required this.unreconciled,required this.percent});factory FinanceReconciliationSummary.fromSupabase(Map<String,dynamic>d){double n(v)=>v is num?v.toDouble():double.tryParse('${v??''}')??0;int i(v)=>v is num?v.toInt():int.tryParse('${v??''}')??0;return FinanceReconciliationSummary(customerInvoices:i(d['customer_invoice_count']),customerOpen:i(d['customer_open_receivable_count']),customerOpenAmount:n(d['customer_open_receivable_amount']),farmerOpen:i(d['farmer_open_settlement_count']),farmerOpenAmount:n(d['farmer_open_settlement_amount']),unbatched:n(d['farmer_unbatched_payout_amount']),bankOpen:i(d['bank_open_transaction_count']),bankOpenAmount:n(d['bank_open_transaction_amount']),sourceAmount:n(d['finance_source_amount']),matchedAmount:n(d['bank_matched_source_amount']),unreconciled:n(d['bank_unreconciled_source_amount']),percent:n(d['reconciliation_percent']));}}
class FinanceReconciliationChain {final String flow,key,id,counterparty,reference,stages,status,detail;final DateTime? date;final double gross,adjustment,net,cashIn,cashOut,matchedIn,matchedOut,openBalance,unreconciled;const FinanceReconciliationChain({required this.flow,required this.key,required this.id,required this.counterparty,required this.reference,required this.stages,required this.status,required this.detail,required this.date,required this.gross,required this.adjustment,required this.net,required this.cashIn,required this.cashOut,required this.matchedIn,required this.matchedOut,required this.openBalance,required this.unreconciled});factory FinanceReconciliationChain.fromSupabase(Map<String,dynamic>d){double n(v)=>v is num?v.toDouble():double.tryParse('${v??''}')??0;return FinanceReconciliationChain(flow:'${d['flow_type']??''}',key:'${d['chain_key']??''}',id:'${d['primary_id']??''}',counterparty:'${d['counterparty']??''}',reference:'${d['reference_label']??''}',stages:'${d['stage_summary']??''}',status:'${d['reconciliation_status']??''}',detail:'${d['detail']??''}',date:DateTime.tryParse('${d['source_date']??''}'),gross:n(d['gross_amount']),adjustment:n(d['adjustment_amount']),net:n(d['net_financial_amount']),cashIn:n(d['expected_cash_in']),cashOut:n(d['expected_cash_out']),matchedIn:n(d['bank_matched_in']),matchedOut:n(d['bank_matched_out']),openBalance:n(d['open_balance']),unreconciled:n(d['unreconciled_amount']));}}
Future<FinanceReconciliationSummary> fetchFinanceReconciliationSummary()async{await requireAdminAccess();final r=await supabase.rpc('admin_finance_reconciliation_summary');final m=r is List&&r.isNotEmpty?r.first:r;if(m is Map)return FinanceReconciliationSummary.fromSupabase(Map<String,dynamic>.from(m));throw Exception('Finance reconciliation summary could not be loaded.');}
Future<List<FinanceReconciliationChain>> fetchFinanceReconciliationChains({String flow='all',String status='attention',String search=''})async{await requireAdminAccess();final r=await supabase.rpc('admin_list_finance_reconciliation_chains',params:{'p_flow':flow,'p_status':status,'p_search':search.trim(),'p_limit':250});return (r as List).map((e)=>FinanceReconciliationChain.fromSupabase(Map<String,dynamic>.from(e as Map))).toList();}
class FinanceReconciliationScreen extends StatefulWidget{const FinanceReconciliationScreen({super.key});@override State<FinanceReconciliationScreen> createState()=>_FinanceReconciliationScreenState();}
